"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["65427"],{52080(e){e.exports=JSON.parse('{"id":"V4-007","slug":"financial-adviser","term":"Financial Adviser","also_known_as":[],"difficulty":"Beginner","definition":"A financial adviser is a professional who gives advice on managing money, such as investing, retirement planning, insurance, tax and estate planning, usually for a fee or commission.","explanation":["Financial advisers help people make decisions about their finances. Their services can range from a one-off plan to ongoing management of a client\u2019s investments and regular reviews.","Advisers are paid in different ways. Fee-only advisers charge a fixed fee, an hourly rate or a percentage of the assets they manage. Others earn commissions from the products they recommend, which can create conflicts of interest. Some use a mix of both.","For example, a couple approaching retirement might pay an adviser to review their pensions and savings, estimate how much income they can safely draw and recommend how to invest.","Rules on financial advice differ by country. Many countries require advisers to be licensed or authorised, to recommend only suitable products and to disclose their fees. Some advisers have a legal duty to act in the client\u2019s best interest, known as a fiduciary duty. Before hiring an adviser, it is worth checking their qualifications, regulatory status, how they are paid and whether they are independent or restricted to certain products. The spelling financial advisor is also widely used."],"note":"","total":1725,"prev":{"slug":"financial-action-task-force","term":"Financial Action Task Force (FATF)"},"next":{"slug":"financial-buyer","term":"Financial Buyer"}}')}}]);